#include <bits/stdc++.h>
using namespace std;

int n, m;

// Labels each 4-connected component of 1-cells; returns component sizes.
vector<int> label(const vector<string> &g, vector<int> &comp) {
    comp.assign(n * m, -1);
    vector<int> sizes, stack;
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int s = 0; s < n * m; s++) {
        if (comp[s] >= 0 || g[s / m][s % m] != '1') continue;
        int id = sizes.size(), size = 0;
        comp[s] = id;
        stack.push_back(s);
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            size++;
            int r = u / m, c = u % m;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                int v = nr * m + nc;
                if (comp[v] < 0 && g[nr][nc] == '1') comp[v] = id, stack.push_back(v);
            }
        }
        sizes.push_back(size);
    }
    return sizes;
}

int main() {
    cin >> n >> m;
    vector<string> a(n), b(n);
    for (auto &r : a) cin >> r;
    for (auto &r : b) cin >> r;
    vector<int> ca, cb;
    vector<int> sa = label(a, ca), sb = label(b, cb);
    // A component of b equals a component of a as a cell set iff all its cells share one
    // a-component and both have the same size.
    vector<int> owner(sb.size(), -2);
    for (int u = 0; u < n * m; u++) {
        if (cb[u] < 0) continue;
        int &o = owner[cb[u]];
        if (o == -2) o = ca[u];
        else if (o != ca[u]) o = -1;
    }
    int answer = 0;
    for (size_t i = 0; i < sb.size(); i++)
        if (owner[i] >= 0 && sa[owner[i]] == sb[i]) answer++;
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static int n, m;

    // Labels each 4-connected component of 1-cells into comp; returns component sizes.
    static int[] label(String[] g, int[] comp) {
        Arrays.fill(comp, -1);
        int[] sizes = new int[n * m + 1];
        int count = 0;
        int[] stack = new int[n * m];
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        for (int s = 0; s < n * m; s++) {
            if (comp[s] >= 0 || g[s / m].charAt(s % m) != '1') continue;
            int id = count++, size = 0, top = 0;
            comp[s] = id;
            stack[top++] = s;
            while (top > 0) {
                int u = stack[--top];
                size++;
                int r = u / m, c = u % m;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    int v = nr * m + nc;
                    if (comp[v] < 0 && g[nr].charAt(nc) == '1') {
                        comp[v] = id;
                        stack[top++] = v;
                    }
                }
            }
            sizes[id] = size;
        }
        return Arrays.copyOf(sizes, count);
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        String[] a = new String[n], b = new String[n];
        for (int i = 0; i < n; i++) a[i] = st.nextToken();
        for (int i = 0; i < n; i++) b[i] = st.nextToken();
        int[] ca = new int[n * m], cb = new int[n * m];
        int[] sa = label(a, ca), sb = label(b, cb);
        // A component of b equals a component of a as a cell set iff all its cells share one
        // a-component and both have the same size.
        int[] owner = new int[sb.length];
        Arrays.fill(owner, -2);
        for (int u = 0; u < n * m; u++) {
            if (cb[u] < 0) continue;
            int o = owner[cb[u]];
            if (o == -2) owner[cb[u]] = ca[u];
            else if (o != ca[u]) owner[cb[u]] = -1;
        }
        int answer = 0;
        for (int i = 0; i < sb.length; i++)
            if (owner[i] >= 0 && sa[owner[i]] == sb[i]) answer++;
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var n, m int

// label marks each 4-connected component of 1-cells in comp and returns component sizes.
func label(g []string, comp []int) []int {
	for i := range comp {
		comp[i] = -1
	}
	sizes := []int{}
	stack := []int{}
	dr := []int{1, -1, 0, 0}
	dc := []int{0, 0, 1, -1}
	for s := 0; s < n*m; s++ {
		if comp[s] >= 0 || g[s/m][s%m] != '1' {
			continue
		}
		id, size := len(sizes), 0
		comp[s] = id
		stack = append(stack, s)
		for len(stack) > 0 {
			u := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			size++
			r, c := u/m, u%m
			for d := 0; d < 4; d++ {
				nr, nc := r+dr[d], c+dc[d]
				if nr < 0 || nr >= n || nc < 0 || nc >= m {
					continue
				}
				v := nr*m + nc
				if comp[v] < 0 && g[nr][nc] == '1' {
					comp[v] = id
					stack = append(stack, v)
				}
			}
		}
		sizes = append(sizes, size)
	}
	return sizes
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m)
	a := make([]string, n)
	b := make([]string, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	for i := range b {
		fmt.Fscan(in, &b[i])
	}
	ca := make([]int, n*m)
	cb := make([]int, n*m)
	sa := label(a, ca)
	sb := label(b, cb)
	// A component of b equals a component of a as a cell set iff all its cells share one
	// a-component and both have the same size.
	owner := make([]int, len(sb))
	for i := range owner {
		owner[i] = -2
	}
	for u := 0; u < n*m; u++ {
		if cb[u] < 0 {
			continue
		}
		if owner[cb[u]] == -2 {
			owner[cb[u]] = ca[u]
		} else if owner[cb[u]] != ca[u] {
			owner[cb[u]] = -1
		}
	}
	answer := 0
	for i := range sb {
		if owner[i] >= 0 && sa[owner[i]] == sb[i] {
			answer++
		}
	}
	fmt.Println(answer)
}
